def squash(s: str) -> str:
    if not s:
        return ""

    def esc(c: str) -> str:
        if c.isdigit() or c == "\\":
            return "\\" + c
        return c

    res = []
    n = len(s)
    i = 0

    while i < n:
        j = i
        while j < n and s[j] == s[i]:
            j += 1
        length = j - i
        escaped = esc(s[i])
        if length >= 3:
            res.append(f"{length}{escaped}")
        else:
            res.append(escaped * length)
        i = j

    return "".join(res)
